def test(lines,name,files):
    dd=f"/tmp/probe/p3/{name}"; os.makedirs(dd,exist_ok=True)
    for fn,content in files.items(): open(os.path.join(dd,fn),"w").write(content)
    open(os.path.join(dd,"book.book"),"w").write("title: T\nauthor: A\noutput.html: out.html\noutput.tex: out.tex\noutput.epub: out.epub\n"+lines)
    r=subprocess.run(["/workspace/executable","book.book"],capture_output=True,cwd=dd)
    print("\n==",name,repr(lines),"err",r.stderr.decode())
    if os.path.exists(os.path.join(dd,"out.html")):
        txt=clean(open(os.path.join(dd,"out.html")).read())
        s=txt.find('<div id = "chapter-'); print("HTML chapters:", txt[s:txt.find('</body>')])
        m=re.search(r'<nav.*?</nav>',txt,re.S); print("TOC:", m.group(0) if m else None)
    if os.path.exists(os.path.join(dd,"out.tex")):
        txt=open(os.path.join(dd,"out.tex")).read(); m=re.search(r'\\maketitle(.*)\\end\{document\}',txt,re.S); print("TEX:", m.group(1) if m else "")
    if os.path.exists(os.path.join(dd,"out.epub")):
        import zipfile; z=zipfile.ZipFile(os.path.join(dd,"out.epub")); print("EPUB files",z.namelist())
        for n in z.namelist():
