# ---------------- Template engine -----------------
class TemplateError(Exception):
    def __init__(self, msg, line=None, snippet=None, reason=None):
        super().__init__(msg)
        self.line=line; self.snippet=snippet; self.reason=reason

def tex_token_re():
    return re.compile(r"(<<[^>]+?>>|<#.*?#>)", re.S)
def html_token_re():
    return re.compile(r"(\{\{.*?\}\}|\{%.*?%\})", re.S)

def lookup_var(name, ctx):
    name=name.strip()
    if not name:
        return ""
    # literals
    if (name.startswith('"') and name.endswith('"')) or (name.startswith("'") and name.endswith("'")):
        return name[1:-1]
    if re.fullmatch(r"-?\d+", name): return int(name)
    parts=name.split(".")
    cur=ctx
    for p in parts:
        if isinstance(cur, dict) and p in cur:
            cur=cur[p]
        elif hasattr(cur, p):
            cur=getattr(cur,p)
        else:
            raise TemplateError(f"not found in this scope", reason="not found in this scope")
    return cur

def eval_cond(expr, ctx):
    expr=expr.strip()
    if expr.startswith("not "):
        return not truthy(eval_cond(expr[4:], ctx))
    if "==" in expr:
        a,b=expr.split("==",1); return lookup_var(a,ctx)==lookup_var(b.strip(),ctx) if False else str(lookup_var(a,ctx))==str(eval_literal(b,ctx))
    if "!=" in expr:
        a,b=expr.split("!=",1); return str(lookup_var(a,ctx))!=str(eval_literal(b,ctx))
    try:
        v=lookup_var(expr,ctx)
    except TemplateError:
        raise
    return truthy(v)

def eval_literal(s, ctx):
    s=s.strip()
    if (s.startswith('"') and s.endswith('"')) or (s.startswith("'") and s.endswith("'")): return s[1:-1]
    return s

def truthy(v):
    if v is None or v is False: return False
    if v=="": return False
    if v==0: return False
    return True

def render_template(text, ctx, style="html"):
    try:
        return _render_template_inner(text, ctx, style, orig=text)
    except TemplateError as e:
        # compute line of offending token if possible
        if e.line is None:
            # find variable in text
            e.line = 1
        raise

def _render_template_inner(text, ctx, style, orig=None):
    if style=="tex":
        token_re=tex_token_re()
        parts=token_re.split(text)
        # process with a stack approach using recursion on if blocks: easier convert to node list
        nodes=parse_template_nodes(parts, style)
        return render_nodes(nodes, ctx, style)
    else:
        token_re=html_token_re()
        parts=token_re.split(text)
        nodes=parse_template_nodes(parts, style)
        return render_nodes(nodes, ctx, style)

def parse_template_nodes(parts, style):
    # returns list of nodes; handle if/for nesting via recursive parser over parts index
    nodes, idx, stop = _parse_nodes(parts, 0, style, ())
    return nodes

def _parse_nodes(parts, i, style, stop_tags):
    nodes=[]
    while i < len(parts):
        part=parts[i]
        if style=="tex":
            if part.startswith("<#") and part.endswith("#>"):
                inner=part[2:-2].strip()
                if any(inner==t or inner.startswith(t+" ") for t in stop_tags):
                    return nodes, i, inner
                if inner.startswith("if "):
                    cond=inner[3:].strip()
                    body, j, stop = _parse_nodes(parts, i+1, style, ("else","endif"))
                    else_body=[]
                    if stop and stop.startswith("else"):
                        else_body, j, stop2 = _parse_nodes(parts, j+1, style, ("endif",))
                    nodes.append(("if",cond,body,else_body)); i=j+1; continue
                elif inner.startswith("for "):
                    m=re.match(r"for\s+(\w+)\s+in\s+(.+)",inner)
                    body, j, stop = _parse_nodes(parts, i+1, style, ("endfor",))
                    nodes.append(("for",m.group(1),m.group(2).strip(),body)); i=j+1; continue
                else:
                    i+=1; continue
            elif part.startswith("<<") and part.endswith(">>"):
                nodes.append(("var",part[2:-2].strip())); i+=1; continue
            else:
                if part: nodes.append(("text",part))
                i+=1; continue
        else:
            if part.startswith("{%") and part.endswith("%}"):
                inner=part[2:-2].strip()
                if any(inner==t or inner.startswith(t+" ") for t in stop_tags):
                    return nodes, i, inner
                if inner.startswith("if "):
                    cond=inner[3:].strip()
                    body, j, stop = _parse_nodes(parts, i+1, style, ("else","endif"))
                    else_body=[]
                    if stop and stop.startswith("else"):
                        else_body, j, stop2 = _parse_nodes(parts, j+1, style, ("endif",))
                    nodes.append(("if",cond,body,else_body)); i=j+1; continue
                elif inner.startswith("for "):
                    m=re.match(r"for\s+(\w+)\s+in\s+(.+)",inner)
                    if m:
                        body, j, stop = _parse_nodes(parts, i+1, style, ("endfor",))
                        nodes.append(("for",m.group(1),m.group(2).strip(),body)); i=j+1; continue
                    i+=1; continue
                elif inner.startswith("elif "):
                    return nodes, i, inner
                else:
                    i+=1; continue
            elif part.startswith("{{") and part.endswith("}}"):
                nodes.append(("var",part[2:-2].strip())); i+=1; continue
            else:
                if part: nodes.append(("text",part))
                i+=1; continue
    return nodes, i, None

def render_nodes(nodes, ctx, style):
    out=[]
    for node in nodes:
        if node[0]=="text": out.append(node[1])
        elif node[0]=="var":
            try:
                v=lookup_var(node[1],ctx)
            except TemplateError as e:
                # attach line info: approximate by searching? caller may handle
                raise
            out.append("" if v is None else str(v))
        elif node[0]=="if":
            cond=eval_cond(node[1],ctx)
            out.append(render_nodes(node[2] if cond else node[3], ctx, style))
        elif node[0]=="for":
            _,var,expr,body=node
            try: seq=lookup_var(expr,ctx)
            except TemplateError: seq=[]
            if seq:
                for item in seq:
                    c=dict(ctx); c[var]=item
                    out.append(render_nodes(body,c,style))
    return "".join(out)

