class YamlErr(Exception): pass
class YVal:
    def __init__(self,kind,value,raw=None):
        self.kind=kind; self.value=value; self.raw=raw if raw is not None else value
    def __repr__(self): return f"YVal({self.kind},{self.value!r})"

def rust_debug_str(s):
    out='"'
    for ch in str(s):
        if ch=='"': out+='\\"'
        elif ch=='\\': out+='\\\\'
        elif ch=='\n': out+='\\n'
        elif ch=='\r': out+='\\r'
        elif ch=='\t': out+='\\t'
        else: out+=ch
    return out+'"'

def format_yval(v):
    if v.kind=="String": return f"String({rust_debug_str(v.value)})"
    if v.kind=="Integer": return f"Integer({v.value})"
    if v.kind=="Real": return f"Real({rust_debug_str(v.raw)})"
    if v.kind=="Boolean": return f"Boolean({'true' if v.value else 'false'})"
    if v.kind=="Null": return "Null"
    if v.kind=="Array": return "Array(["+", ".join(format_yval(x) for x in v.value)+"])"
    if v.kind=="Hash": return "Hash({...})"
    return v.kind

def parse_yaml_scalar(s, global_col_offset=0):
    s_orig=s
    s=s.strip()
    if s=="": return YVal("Null",None)
    # flow list
    if s.startswith("["):
        if not s.endswith("]"):
            raise YamlErr("while parsing a flow sequence, expected ',' or ']' at line 2 column 1")
        inner=s[1:-1].strip()
        if inner=="": return YVal("Array",[])
        items=[]
        # split commas respecting quotes/brackets
        depth=0; q=None; cur=""
        for ch in inner:
            if q:
                cur+=ch
                if ch==q: q=None
            elif ch in "\"'": q=ch; cur+=ch
            elif ch=='[': depth+=1; cur+=ch
            elif ch==']': depth-=1; cur+=ch
            elif ch==',' and depth==0:
                items.append(parse_yaml_scalar(cur)); cur=""
            else: cur+=ch
        if cur.strip()!="" or inner.endswith(","): items.append(parse_yaml_scalar(cur))
        return YVal("Array",items)
    if s.startswith('"'):
        # double quoted
        if len(s)>=2 and s.endswith('"'):
            body=s[1:-1]
            try: val=json.loads('"'+body.replace('"','\\"')+'"' if False else s)
            except Exception: val=body
            # json.loads handles escapes; but if s contains single quotes fine
            try: val=json.loads(s)
            except Exception: val=body.encode().decode('unicode_escape')
            return YVal("String",str(val))
        else:
            raise YamlErr("while parsing a quoted scalar, found unexpected end of stream")
    if s.startswith("'"):
        if len(s)>=2 and s.endswith("'"):
            return YVal("String", s[1:-1].replace("''","'"))
        raise YamlErr("while parsing a quoted scalar, found unexpected end of stream")
    # plain: strip comment  # preceded by space
    if " #" in s:
        s=s[:s.index(" #")].rstrip()
    # check mapping value inside
    if ": " in s or s.endswith(":"):
        idx=s.find(": ")
        col = global_col_offset + (idx+1) + 1  # 1-based col of colon?
        raise YamlErr(f"mapping values are not allowed in this context at line 1 column {col}")
    low=s
    if low in ("true","false"): return YVal("Boolean", low=="true")
    if low in ("null","Null","NULL","~"): return YVal("Null",None)
    if re.fullmatch(r"-?\d+", s):
        try: return YVal("Integer", int(s))
        except: pass
    if re.fullmatch(r"-?(\d+\.\d*|\.\d+|\d+)([eE][-+]?\d+)?", s) and ("." in s or "e" in s.lower()):
        return YVal("Real", float(s), raw=s)
    return YVal("String", s)

def parse_single_yaml_value(text):
    """for --set values: returns YVal or raises ValueError with crowbook message"""
    t=text.strip()
    if t=="":
        raise ValueError("empty")
    # yaml-rust parses a document; use scalar/list parser
    if t.startswith("[") or t.startswith('"') or t.startswith("'"):
        return parse_yaml_scalar(t)
    # plain scalar possibly containing spaces - keep as one string
    # but check numbers/bools
    return parse_yaml_scalar(t)

