    if opts.get("input.clean.smart_quotes", True):
        s = smart_quotes(s)
    if opts.get("input.clean.ligature.dashes", False):
        s = s.replace("---","—").replace("--","–")
    if opts.get("input.clean.ligature.guillemets", False):
        s = s.replace("<<","«").replace(">>","»")
