        s = french_guillemets(s)
        # punctuation narrow nbsp
        s = re.sub(r"([^\s])[\s\u00a0\u202f]+([!?;,%])", lambda m: m.group(1)+NNBSP+m.group(2), s)
        s = re.sub(r"([^\s])[\s\u00a0\u202f]+(:)", lambda m: m.group(1)+NBSP+m.group(2), s)
        # normalize nbsp not before punct / around guillemets handled (remaining becomes space)
        # Replace NBSP that is not immediately before : ; ! ? % or after « or before »
