            i=m.start(); prev=s[i-1] if i>0 else ""; nxt=s[i+1] if i+1<len(s) else ""
            if nxt in ":;!?%" or prev=="«" or nxt=="»":
                return m.group(0)
            return " "
        s = re.sub(r"\u00a0", nb_repl, s)
    return s

def french_guillemets(s):
    # spaces after « and before »
    out=""; i=0
    starts = s.lstrip().startswith("«")
    while i < len(s):
        if s[i]=="«":
            out+="«"; i+=1
            j=i
            while j<len(s) and s[j] in " \u00a0\u202f": j+=1
            if j>i and j<len(s):
                out += NBSP if out.strip()=="«" and s[: max(0,len(out)-1)].strip()=="" else NNBSP
                i=j
            continue
        if s[i] in " \u00a0\u202f":
            j=i
            while j<len(s) and s[j] in " \u00a0\u202f": j+=1
            if j<len(s) and s[j]=="»":
                # decide: if segment from last « to here contains no regular space before? approximate startswith
                prefix=out
                ch = NBSP if prefix.strip().startswith("«") and " " not in prefix.strip()[1:] else NNBSP
                if prefix.strip()=="": ch=NNBSP
                out+=ch+"»"; i=j+1; continue
            out+=s[i:j]; i=j; continue
        out+=s[i]; i+=1
    return out

def smart_quotes(s):
    # paired single quotes
    def repl_pair(m):
        return "‘"+m.group(1)+"’"
    # pair with no leading/trailing spaces inside, allow following punctuation outside (handled by regex)
    s2 = re.sub(r"'([^'\n]*[^\s'])'", repl_pair, s)
    s2 = re.sub(r"'([^\s'])'", repl_pair, s2)
    # double quotes pair handling via scanning below on result (do doubles first actually)
    s = s2
    # apostrophes remaining
    out=[]; i=0
    while i < len(s):
        ch=s[i]
        if ch=="'":
            prev=s[i-1] if i>0 else ""
            nxt=s[i+1] if i+1<len(s) else ""
            rest=s[i+1:]
            word_match=re.match(r"[A-Za-zÀ-ÿ]+|\d+", rest)
            word=word_match.group(0).lower() if word_match else ""
            if prev.isalnum() or prev in "’":
                out.append("’")
            elif word in ("tis","cause","cos","til","em","cause","twas","twill") or (nxt.isdigit()):
                out.append("’")
            elif nxt and not nxt.isspace() and (prev=="" or prev.isspace() or prev in "([{\"“‘"):
                out.append("‘")
            elif prev and not prev.isspace():
                out.append("’")
            else:
                out.append(ch)
            i+=1; continue
        out.append(ch); i+=1
    s="".join(out)
    # double quotes scanning
    out=[]; i=0
    while i < len(s):
        ch=s[i]
        if ch=='"':
            prev=s[i-1] if i>0 else ""
            nxt=s[i+1] if i+1<len(s) else ""
            if (prev=="" or prev.isspace() or prev in "([{‘") and nxt and not nxt.isspace():
                out.append("“")
            else:
                out.append("”")
            i+=1; continue
        out.append(ch); i+=1
    return "".join(out)

