        elif k=="image": out+=plain_text_of_inline(n[1])
        elif k=="footref": out+=f"[{n[1]}]"
        elif k=="hardbreak" or k=="softbreak": out+=" "
    return out

def normalize_label(s):
    return re.sub(r"\s+"," ",s.strip().lower())

class InlineParser:
    def __init__(self, text, refs, opts, lang, html_as_text=True, superscript=False):
        self.s=text; self.refs=refs or {}; self.opts=opts; self.lang=lang; self.html_as_text=html_as_text; self.superscript=superscript
    def parse(self):
        nodes, _ = self.parse_until(0, None)
        return self.clean_nodes(nodes)
    def clean_nodes(self, nodes):
        out=[]
        for n in nodes:
            if n[0]=="text":
                out.append(("text", clean_text(n[1], self.opts, self.lang)))
            elif n[0] in ("emph","strong","strike","sup","sub"):
                out.append((n[0], self.clean_nodes(n[1])))
            elif n[0]=="link":
                out.append(("link", self.clean_nodes(n[1]), n[2], n[3]))
            elif n[0]=="image":
                out.append(("image", self.clean_nodes(n[1]), n[2], n[3]))
            else:
                out.append(n)
        return out
    def parse_until(self, i, endchar):
        nodes=[]; buf=""
        s=self.s
        def flush():
            nonlocal buf
            if buf: nodes.append(("text",buf)); buf=""
        while i < len(s):
            ch=s[i]
            # escape
            if ch=="\\" and i+1<len(s) and s[i+1] in "\\`*_{}[]()#+-.!|~<>\"'":
                buf+=s[i+1]; i+=2; continue
            if ch=="\\" and i+1<len(s) and s[i+1]=="\n":
                flush(); nodes.append(("hardbreak",)); i+=2; continue
            # hard break two spaces before newline handled at paragraph level? inline string includes \n
            if ch=="\n":
                # check preceding spaces in buf
                if buf.endswith("  "):
                    buf=buf[:-2]; flush(); nodes.append(("hardbreak",)); i+=1
                    # skip spaces at line start
                    while i<len(s) and s[i]==" ": i+=1
                    continue
                buf+="\n"; i+=1; continue
            # code span
            if ch=="`":
                m=re.match(r"`+", s[i:])
                run=m.group(0); end=s.find(run, i+len(run))
                if end!=-1:
                    # ensure closing run not part of longer? simplify
                    content=s[i+len(run):end]
                    content=content.replace("\n"," ")
                    if len(content)>=2 and content[0]==" " and content[-1]==" " and content.strip()!="":
                        content=content[1:-1]
                    flush(); nodes.append(("code",content)); i=end+len(run); continue
                buf+=ch; i+=1; continue
            # footnotes / links / images
            if ch=="!" and i+1<len(s) and s[i+1]=="[":
                res=self.try_link(i, image=True)
                if res: flush(); nodes.append(res[0]); i=res[1]; continue
                buf+=ch; i+=1; continue
            if ch=="[":
                # footnote ref
                if i+1<len(s) and s[i+1]=="^":
                    end=s.find("]", i+2)
                    if end!=-1:
                        label=s[i+2:end]
                        flush(); nodes.append(("footref",label)); i=end+1; continue
                res=self.try_link(i, image=False)
                if res: flush(); nodes.append(res[0]); i=res[1]; continue
                buf+=ch; i+=1; continue
            # autolink / html
            if ch=="<":
                m=re.match(r"<((?:https?|ftp)://[^>\s]+|[^>\s]+@[^>\s]+)>", s[i:])
                if m:
                    dest=m.group(1)
                    if "@" in dest and "://" not in dest:
                        href="mailto:"+dest; text=dest
                    else: href=dest; text=dest
                    flush(); nodes.append(("link",[("text",text)],href,None)); i+=len(m.group(0)); continue
                m=re.match(r"</?[A-Za-z][^>]*>", s[i:])
                if m:
                    if self.html_as_text:
                        buf+=m.group(0)
                    # else drop tag
                    i+=len(m.group(0)); continue
                buf+=ch; i+=1; continue
            # superscript / subscript
            if self.superscript and ch=="^":
                if i+1<len(s) and s[i+1]=="^": buf+="^^"; i+=2; continue
                end=s.find("^", i+1)
                if end!=-1 and end>i+1 and " " not in s[i+1:end] or (end!=-1 and end>i+1 and "\n" not in s[i+1:end]):
                    # observed a^b^ works, content can? keep no newline
                    if end!=-1 and end>i+1 and "\n" not in s[i+1:end]:
                        flush(); sub=InlineParser(s[i+1:end], self.refs, self.opts, self.lang, self.html_as_text, self.superscript).parse(); nodes.append(("sup",sub)); i=end+1; continue
                buf+=ch; i+=1; continue
            if self.superscript and ch=="~":
                if i+1<len(s) and s[i+1]=="~": buf+="~~"; i+=2; continue
                end=self.find_single_tilde(s,i+1)
                if end!=-1:
                    flush(); sub=InlineParser(s[i+1:end], self.refs, self.opts, self.lang, self.html_as_text, self.superscript).parse(); nodes.append(("sub",sub)); i=end+1; continue
                buf+=ch; i+=1; continue
            # emphasis / strike
            if ch in "*_~" and not (self.superscript and ch=="~" and False):
                res=self.try_emphasis(i)
                if res: flush(); nodes.append(res[0]); i=res[1]; continue
                buf+=ch; i+=1; continue
            # bare links
            if ch in "hw" and (i==0 or s[i-1].isspace() or s[i-1] in "([\"“'"):
                m=re.match(r"(https?://[^\s<>]+|www\.[^\s<>]+)", s[i:])
                if m:
                    url=m.group(0); orig=url
                    # strip trailing punctuation
                    while url and url[-1] in ".,;:!?":
                        url=url[:-1]; orig=orig[:-1]
                    while url.endswith(")") and url.count("(")<url.count(")"):
                        url=url[:-1]; orig=orig[:-1]
                    href=url if url.startswith("http") else "http://"+url
                    flush(); nodes.append(("link",[("text",url)],href,None)); i+=len(orig); continue
            buf+=ch; i+=1
        flush()
        return nodes, i
    def find_single_tilde(self,s,pos):
        i=pos
        while True:
            j=s.find("~",i)
            if j==-1: return -1
            if (j+1>=len(s) or s[j+1]!="~") and (j==0 or s[j-1]!="~"): return j
            i=j+1
    def try_link(self,i,image=False):
        s=self.s
        start=i+1 if image else i  # '[' position
        # find matching ]
        depth=0; j=start
        while j<len(s):
            if s[j]=="\\" : j+=2; continue
            if s[j]=="[": depth+=1
            elif s[j]=="]":
                depth-=1
                if depth==0: break
            j+=1
        if j>=len(s): return None
        text_inner=s[start+1:j]
        after=j+1
        dest=None; title=None
        # inline dest
        if after<len(s) and s[after]=="(":
            # find matching ) respecting quotes
            depth=0; k=after; q=None
            while k<len(s):
                c=s[k]
                if q:
                    if c==q: q=None
                elif c in "\"'": q=c
                elif c=="(": depth+=1
                elif c==")":
                    depth-=1
                    if depth==0: break
                k+=1
            if k>=len(s): return None
            inner=s[after+1:k].strip()
            # parse dest title
            m=re.match(r"^(<([^>]+)>|\S+)(?:\s+(?:\"([^\"]*)\"|'([^']*)'|\(([^)]*)\)))?\s*$", inner, re.S)
            if not m: return None
            dest=m.group(2) if m.group(2) else m.group(1)
            title=m.group(3) or m.group(4) or m.group(5)
            end=k+1
            alt_nodes=InlineParser(text_inner,self.refs,self.opts,self.lang,self.html_as_text,self.superscript).parse()
            kind="image" if image else "link"
            return (kind, alt_nodes, dest, title), end
        # reference
        if after<len(s) and s[after]=="[":
            end2=s.find("]",after+1)
            if end2!=-1:
                label=s[after+1:end2]
                key=normalize_label(label if label else text_inner)
                if key in self.refs:
                    dest,title=self.refs[key]
                    alt_nodes=InlineParser(text_inner,self.refs,self.opts,self.lang,self.html_as_text,self.superscript).parse()
                    kind="image" if image else "link"
                    return (kind, alt_nodes, dest, title), end2+1
                else:
                    return None
        # shortcut reference
        key=normalize_label(text_inner)
        if key in self.refs:
            dest,title=self.refs[key]
            alt_nodes=InlineParser(text_inner,self.refs,self.opts,self.lang,self.html_as_text,self.superscript).parse()
            kind="image" if image else "link"
            return (kind, alt_nodes, dest, title), after
        return None
    def try_emphasis(self,i):
        s=self.s; ch=s[i]
        # count run
        j=i
        while j<len(s) and s[j]==ch: j+=1
        run=j-i
        if ch=="~":
            if self.superscript: return None
            if run>2: return None
            delim="~"*run
            end=s.find(delim,i+run)
            if end==-1 or end==i+run: return None
            # ensure closing not longer for single? simplify
            inner=s[i+run:end]
            nodes=InlineParser(inner,self.refs,self.opts,self.lang,self.html_as_text,self.superscript).parse()
            return ("strike",nodes), end+run
        # * or _
        if run>3: return None
        # underscore intraword check
        if ch=="_":
            prev=s[i-1] if i>0 else ""
            if prev.isalnum(): return None
        delim=ch*run
        # find closing
        pos=i+run
        while True:
            end=s.find(delim,pos)
            if end==-1: return None
            # for underscore, closing must not be followed by alnum if preceded?
            if ch=="_":
                after=s[end+run] if end+run<len(s) else ""
                if after.isalnum():
                    pos=end+run; continue
            inner=s[i+run:end]
            if inner=="" or inner[0].isspace() or inner[-1].isspace():
                pos=end+run; continue
            break
        nodes=InlineParser(inner,self.refs,self.opts,self.lang,self.html_as_text,self.superscript).parse()
        if run==1: return ("emph",nodes), end+run
        if run==2: return ("strong",nodes), end+run
        if run==3: return ("emph",[("strong",nodes)]), end+run
        return None

def parse_inline(text, refs, opts, lang):
    superscript = bool(opts.get("crowbook.markdown.superscript", False))
    html_as_text = bool(opts.get("crowbook.html_as_text", True))
    # entities decoding will be done at render time; but parser needs & handling as text
    p=InlineParser(text, refs, opts, lang, html_as_text, superscript)
    nodes=p.parse()
    # postprocess: split text nodes for entities? Keep as text, renderer decodes entities via html parser? We'll decode here common entities
    return decode_entities_in_nodes(nodes)

ENTITY_MAP = {"copy":"©","amp":"&","lt":"<","gt":">","quot":'"',"apos":"'","nbsp":NBSP,"eacute":"é","egrave":"è","agrave":"à","ccedil":"ç","hellip":"…","mdash":"—","ndash":"–","laquo":"«","raquo":"»","rsquo":"’","lsquo":"‘","ldquo":"“","rdquo":"”"}
def decode_entities(s):
    def rep(m):
        ent=m.group(1)
        if ent.startswith("#x") or ent.startswith("#X"):
            try: return chr(int(ent[2:],16))
            except: return m.group(0)
        if ent.startswith("#"):
            try: return chr(int(ent[1:]))
            except: return m.group(0)
        if ent in ENTITY_MAP: return ENTITY_MAP[ent]
        return m.group(0)  # will be escaped at render as &...; but original keeps &unknown; -> renderer will escape & to &amp;
        # To preserve, we mark? Simpler return original; renderer escapes & leading to &amp;unknown; matches.
    return re.sub(r"&([A-Za-z][A-Za-z0-9]+|#[0-9]+|#[xX][0-9A-Fa-f]+);", rep, s)

def decode_entities_in_nodes(nodes):
    out=[]
    for n in nodes:
        if n[0]=="text": out.append(("text", decode_entities(n[1])))
        elif n[0] in ("emph","strong","strike","sup","sub"): out.append((n[0], decode_entities_in_nodes(n[1])))
        elif n[0] in ("link","image"): out.append((n[0], decode_entities_in_nodes(n[1]), n[2], n[3]))
        else: out.append(n)
    return out

