def extract_leading_yaml(text):
    if not text.startswith("---\n") and not text.startswith("---\r\n"):
        return text, None
    lines=text.split("\n")
    if not lines or lines[0].strip()!="---": return text, None
    for idx in range(1,len(lines)):
        if lines[idx].strip()=="---":
            content=lines[1:idx]
            if not any(c.strip() for c in content):
                return text, None
            rest="\n".join(lines[idx+1:])
            return rest, content
    return text, None

def reconstruct_leading_yaml(content_lines, rest):
    return "---\n"+"\n".join(content_lines)+"\n---\n"+rest

def apply_yaml_lines_to_options(opts, lines, book, source_for_err):
    # parse simple key: value lines
    for raw in lines:
        if raw.strip()=="" or raw.lstrip().startswith("#"): continue
        m=re.match(r"^([^:]+):\s*(.*)$", raw)
        if not m: continue
        key=m.group(1).strip(); rest=m.group(2).strip()
        try: yval=parse_yaml_scalar(rest)
        except YamlErr: continue
        if key=="output.html_dir":
            key="output.html.dir"
        val,err=convert_option(key,yval)
        if not err:
            opts[key]=val

