class Logger:
    def __init__(self):
        self.verbose=False; self.quiet=False; self.no_fancy=False; self.force_emoji=False
        self.collected=[]  # list of (level_word, msg)
    @property
    def fancy(self):
        return not self.verbose and not self.no_fancy and not self.quiet
    def emit(self, level, msg, module="crowbook::book"):
        # level: DEBUG INFO WARN ERROR
        msg=tr_msg(str(msg))
        if self.verbose:
            ts=datetime.datetime.now().strftime("%H:%M:%S")
            if level=="DEBUG":
                sys.stderr.write(f"{ts} [DEBUG] (1) {module}: {msg}\n")
            else:
                sys.stderr.write(f"{ts} [{level}] {module}: {msg}\n")
            return
        if self.no_fancy or self.quiet:
            if self.quiet and level in ("INFO","WARN","DEBUG"):
                return
            if level=="DEBUG":
                return
            sys.stderr.write(f"[{level}] {msg}\n")
            return
        # fancy default: collect warnings/errors
        if level in ("WARN","ERROR"):
            self.collected.append(("WARNING" if level=="WARN" else "ERROR", msg))
    def debug(self,msg,module="crowbook::book"): self.emit("DEBUG",msg,module)
    def info(self,msg,module="crowbook::book"): self.emit("INFO",msg,module)
    def warn(self,msg,module="crowbook::book"): self.emit("WARN",msg,module)
    def error(self,msg,module="crowbook::book"): self.emit("ERROR",msg,module)
    def print_collected(self):
        if not self.collected: return
        hdr="WARNING Crowbook exited successfully, but the following errors occurred:"
        if self.force_emoji and self.fancy:
            sys.stderr.write(f"⚠️ {tr_msg(hdr)}\n")
            for lvl,msg in self.collected:
                if lvl=="ERROR": sys.stderr.write(f"💣 ERROR {msg}\n")
                else: sys.stderr.write(f"⚠️ WARNING {msg}\n")
        else:
            sys.stderr.write(tr_msg(hdr)+"\n")
            for lvl,msg in self.collected:
                sys.stderr.write(f"{lvl} {msg}\n")
        self.collected=[]

