def extract_leading_yaml(text):
    if not text.startswith("---\n") and not text.startswith("---\r\n"):
        return text, None
    lines=text.split("\n")
    if not lines or lines[0].strip()!="---": return text, None
    for idx in range(1,len(lines)):
        if lines[idx].strip()=="---":
            content=lines[1:idx]
            if not any(c.strip() for c in content):
                return text, None
            rest="\n".join(lines[idx+1:])
            return rest, content
    return text, None

