# ---------------- Rendering -----------------
class RenderError(Exception): pass

KNOWN_THEMES = {"InspiredGitHub","base16-ocean.dark","base16-eighties.dark","base16-mocha.dark","base16-ocean.light","Solarized (dark)","Solarized (light)"}
# palettes: dict token kind -> (color, bold?)
THEME_IG = {"default":"#323232","keyword":"#a71d5d","string":"#183691","number":"#0086b3","comment":"#969896","function":"#62a35c","type":"#795da3","operator":"#a71d5d"}
THEME_OCEAN = {"default":"#c0c5ce","keyword":"#b48ead","string":"#a3be8c","number":"#d08770","comment":"#65737e","function":"#96b5b4","type":"#ebcb8b","operator":"#96b5b4"}

PY_KEYWORDS=set("def class return if elif else for while import from as with try except finally raise pass break continue and or not in is None True False print len range str int float list dict set tuple lambda yield global nonlocal assert del async await type isinstance".split())
GENERIC_KEYWORDS=set("fn let mut pub struct enum impl trait match if else for while loop return break continue const static type where use mod self Self true false null nil function var int void char bool unsigned long switch case default do sizeof new delete this class extends public private protected static final abstract interface throws try catch finally package import from export async await yield lambda def end begin module require include".split())

def tokenize_code(code, lang):
    # returns list of (kind, text)
    tokens=[]; i=0
    lang=(lang or "").lower()
    keywords = PY_KEYWORDS if lang in ("python","py","python3") else GENERIC_KEYWORDS
    while i<len(code):
        rest=code[i:]
        # comments
        if lang in ("python","py","python3","ruby","bash","sh","shell","yaml","toml","perl") and rest.startswith("#"):
            j=code.find("\n",i); j=len(code) if j==-1 else j
            tokens.append(("comment",code[i:j])); i=j; continue
        if rest.startswith("//"):
            j=code.find("\n",i); j=len(code) if j==-1 else j
            tokens.append(("comment",code[i:j])); i=j; continue
        if rest.startswith("/*"):
            j=code.find("*/",i); j=len(code) if j==-1 else j+2
            tokens.append(("comment",code[i:j])); i=j; continue
        # strings
        if rest[0] in "\"'":
            q=rest[0]; j=i+1
            while j<len(code):
                if code[j]=="\\" : j+=2; continue
                if code[j]==q: j+=1; break
                if code[j]=="\n": break
                j+=1
            tokens.append(("string",code[i:j])); i=j; continue
        # numbers
        m=re.match(r"\b\d+(?:\.\d+)?\b", rest)
        if m: tokens.append(("number",m.group(0))); i+=len(m.group(0)); continue
        # identifiers / keywords
        m=re.match(r"[A-Za-z_][A-Za-z0-9_]*", rest)
        if m:
            word=m.group(0)
            # lookahead function call
            k=i+len(word)
            while k<len(code) and code[k]==" ": k+=1
            if word in keywords:
                kind="keyword"
            elif k<len(code) and code[k]=="(":
                kind="function"
            else:
                kind="default"
            tokens.append((kind,word)); i+=len(word); continue
        # operators of interest
        if rest[0] in "=<>+-*/%!&|^~":
            tokens.append(("operator",rest[0])); i+=1; continue
        tokens.append(("default",rest[0])); i+=1
    # merge same kind
    merged=[]
    for kind,text in tokens:
        if merged and merged[-1][0]==kind: merged[-1]=(kind,merged[-1][1]+text)
        else: merged.append((kind,text))
    return merged

def theme_for(name):
    if name=="base16-ocean.dark": return THEME_OCEAN
    return THEME_IG

class RenderContext:
    def __init__(self, book, fmt):
        self.book=book; self.fmt=fmt  # html, epub, html_dir, tex
        self.opts=book.options
        self.lang=book.options.get("lang","en"); self.loc=locale_for(self.lang)
        self.para_counter=0
        self.images={}; self.image_list=[]
        self.theme_error_emitted=False
        self.highlight_error_emitted=False
        self.current_unit=None
        self.first_para_pending=False
        self.footnote_refs=[]  # per unit, reset
        self.in_footnote=False
    # --- options helpers
    def get_template_content(self, opt_key, default_name):
        path=self.opts.get(opt_key)
        if path:
            full=self.book.joined_path(path) if not os.path.isabs(path) else path
            # resources base templates
            bp=self.opts.get("resources.base_path") or self.opts.get("resources.base_path.templates")
            # templates are relative to cwd? crowbook uses resources.base_path.templates default '.' relative to book? We try joined then cwd
            candidates=[]
            if bp and bp not in (".",):
                candidates.append(os.path.join(self.book.base_dir,bp,path) if self.book.base_dir else os.path.join(bp,path))
            candidates.append(full); candidates.append(path)
            for c in candidates:
                if os.path.exists(c):
                    with open(c,encoding="utf-8") as f: return f.read()
            raise RenderError(f"Could not find file '{path}' for template")
        return get_text(f"templates/{default_name}")
    def resolve_resource_path(self, src, kind="images"):
        # returns filesystem path or None if non-local
        if re.match(r"^(https?|ftp)://",src) or src.startswith("data:"):
            return None
        base=None
        if self.opts.get("resources.base_path"): base=self.opts.get("resources.base_path")
        elif kind=="images": base=self.opts.get("resources.base_path.images")
        elif kind=="files": base=self.opts.get("resources.base_path.files")
        # chapter file dir
        unit_dir=""
        if self.current_unit and self.current_unit.get("path"):
            unit_dir=os.path.dirname(self.current_unit["path"])
        if base and base not in (".",):
            cand=os.path.join(self.book.base_dir,base,src) if self.book.base_dir else os.path.join(base,src)
            if os.path.exists(cand): return cand
        # relative to chapter file dir first, then book dir
        if unit_dir:
            cand=os.path.join(unit_dir,src)
            if os.path.exists(cand): return cand
        cand=self.book.joined_path(src)
        return cand
    def register_image(self, src):
        if re.match(r"^(https?|ftp)://",src) or src.startswith("data:"):
            LOG.warn(f"Resources: book includes non-local image {src}, which might cause problem for proper inclusion.")
            return src, None
        if src in self.images:
            return self.images[src], self.image_paths.get(src) if hasattr(self,"image_paths") else None
        # resolve
        path=self.resolve_resource_path(src,"images")
        if path is None or not os.path.exists(path):
            # display path as crowbook: './src' if relative plain? They used './pic.png'
            disp = src if src.startswith(".") or src.startswith("/") else "./"+src
            raise RenderError(f"{self.current_unit.get('filename') if self.current_unit else self.book.source_name}: Could not find file '{disp}' for image")
        idx=len(self.image_list)
        ext=os.path.splitext(src)[1].lstrip(".") or os.path.splitext(path)[1].lstrip(".")
        name=f"images/image_{idx}.{ext}" if ext else f"images/image_{idx}"
        self.images[src]=name
        if not hasattr(self,"image_paths"): self.image_paths={}
        self.image_paths[src]=path
        self.image_list.append((name,path,src))
        return name,path
    def image_src_for_format(self, src, standalone_embed=False):
        if re.match(r"^(https?|ftp)://",src) or src.startswith("data:"):
            LOG.warn(f"Resources: book includes non-local image {src}, which might cause problem for proper inclusion.")
            return src
        name,path=self.register_image(src)
        if standalone_embed:
            # embed as data uri
            mime=mime_for_ext(os.path.splitext(path or src)[1])
            with open(path,"rb") as f: data=f.read()
            return f"data:{mime};base64,"+base64.b64encode(data).decode()
        return name
    # internal links
    def resolve_link(self, href):
        """returns (new_href_or_tex_key, is_internal, tex_key)"""
        # external?
        if href.startswith("http://") or href.startswith("https://"):
            return href, False, None
        # find chapter match
        file_part=href.split("#")[0]
        # candidate transformations
        candidates=[]
        if file_part:
            candidates.append(file_part)
            # replace extension with .md or append .md
            if "." in os.path.basename(file_part):
                candidates.append(re.sub(r"\.[^.]+$",".md",file_part))
            else:
                candidates.append(file_part+".md")
        else:
            candidates.append(href); candidates.append(href+".md" if href else "")
        for unit in self.book.units:
            if unit["kind"]!="file": continue
            fname=unit["entry"].filename
            if fname in candidates or file_part==fname:
                idx=unit["index"]
                if self.fmt=="html": return f"#chapter-{idx}", True, f"chapter-{idx}"
                if self.fmt=="epub": return f"chapter_{idx:03d}.xhtml", True, f"chapter-{idx}"
                if self.fmt=="html_dir": return f"chapter_{idx:03d}.html", True, f"chapter-{idx}"
                if self.fmt=="tex": return f"chapter-{idx}", True, f"chapter-{idx}"
        # warning message construction: link X or Y  (Y guessed)
        if file_part:
            if "." in os.path.basename(file_part):
                guess=re.sub(r"\.[^.]+$",".md",file_part) if False else file_part
                # observed: nope.md -> nope.md ; ./ch2.md -> ./ch2.md ; mailto -> append .md because contains @? Hmm mailto scheme - treat as no extension
                if file_part.startswith("mailto:"): guess=file_part+".md"
            else:
                guess=file_part+".md"
            LOG.warn(f"Resources: could not find an in-book match for link {file_part} or {guess}")
        else:
            guess=href+".md" if href else ""
            LOG.warn(f"Resources: could not find an in-book match for link {href} or {guess}")
        return href, False, None

def mime_for_ext(ext):
    ext=ext.lower().lstrip(".")
    return {"png":"image/png","jpg":"image/jpeg","jpeg":"image/jpeg","gif":"image/gif","svg":"image/svg+xml","webp":"image/webp","bmp":"image/bmp"}.get(ext,"application/octet-stream")

# ---------------- HTML rendering -----------------
def nnbsp_escape_html(text, ctx):
    # text is raw (unescaped). Escape then process tokens.
    esc=html_escape(text)
    esc=esc.replace('"',"&quot;") if False else esc
    if ctx.fmt in ("html","html_dir"):
        enabled=ctx.opts.get("html.escape_nb_spaces", True)
    else:
        enabled=ctx.opts.get("epub.escape_nb_spaces", True)
    # replace newlines with spaces before tokenizing (soft breaks)
    esc=esc.replace("\n"," ")
    if NNBSP not in esc:
        return esc
    if not enabled:
        return esc
    parts=re.split(r"( )", esc)
    out=""
    for p in parts:
        if NNBSP in p:
            out+=f'<span class = "nnbsp">{p.replace(NNBSP,"&#160;")}</span>'
        else:
            out+=p
    return out

def render_inline_html(nodes, ctx, in_alt=False):
    out=""
    for n in nodes or []:
        k=n[0]
        if k=="text":
            out+=nnbsp_escape_html(n[1],ctx)
        elif k=="code":
            out+=f"<code>{html_escape(n[1])}</code>"
        elif k=="emph": out+=f"<em>{render_inline_html(n[1],ctx,in_alt)}</em>"
        elif k=="strong": out+=f"<b>{render_inline_html(n[1],ctx,in_alt)}</b>"
        elif k=="strike": out+=f"<del>{render_inline_html(n[1],ctx,in_alt)}</del>"
        elif k=="sup": out+=f"<sup>{render_inline_html(n[1],ctx,in_alt)}</sup>"
        elif k=="sub": out+=f"<sub>{render_inline_html(n[1],ctx,in_alt)}</sub>"
        elif k=="hardbreak": out+="<br />\n"
        elif k=="softbreak": out+=" "
        elif k=="link":
            href=n[2] or ""; title=n[3]
            new_href,is_internal,_ = ctx.resolve_link(href) if not in_alt else (href,False,None)
            title_attr=f' title = "{html_escape_attr(title)}"' if title else ""
            out+=f'<a href = "{html_escape_attr(new_href)}"{title_attr}>{render_inline_html(n[1],ctx,in_alt)}</a>'
        elif k=="image":
            src=n[2] or ""; title=n[3]
            standalone = (ctx.fmt=="html")
            src_out=ctx.image_src_for_format(src, standalone_embed=standalone)
            alt_html=render_inline_html(n[1],ctx,True).replace('"',"&quot;")
            out+=f'<img src = "{html_escape_attr(src_out)}" title = "{html_escape_attr(title or "")}" alt = "{alt_html}" />'
        elif k=="footref":
            label=n[1]
            if ctx.current_unit is not None and label not in ctx.footnote_refs:
                ctx.footnote_refs.append(label)
            if ctx.fmt=="epub":
                out+=f'<a  href = "#note-dest-{label}"><sup id = "note-source-{label}">[{label}]</sup></a>'
            else:
                u=(ctx.current_unit["index"]+1) if ctx.current_unit else 1
                out+=f'<a class = "footnote_reference" href = "#note-dest-{u}-{label}" id = "note-source-{u}-{label}"><sup>[{label}]</sup></a>'
    return out

def is_standalone_image_para(block):
    nodes=block.get("inline",[])
    nodes=[n for n in nodes if not (n[0]=="text" and n[1].strip()=="")]
    return len(nodes)==1 and nodes[0][0]=="image"

def render_blocks_html(blocks, ctx, unit, top_level=True):
    out=""
    for b in blocks:
        t=b.get("type")
        if t=="heading":
            info=b.get("heading_info",{})
            L=b.get("level",1)
            title_html=render_inline_html(b["inline"],ctx)
            if info.get("hidden"):
                out+=f'<h{L} id = "link-{info.get("link",1)}"></h{L}>'
                ctx.first_para_pending=True
            elif L==1 and unit.get("kind")=="file":
                # chapter template
                tmpl=ctx.opts.get("html.chapter.template")
                cctx={"has_number":bool(info.get("has_number")),"has_title":info.get("plain","")!="","header":ctx.opts.get("rendering.chapter") or ctx.loc["chapter"],"number":info.get("number_fmt","") if info.get("has_number") else "","title":title_html,"link":info.get("link",1)}
                out+=render_template(tmpl,cctx,"html")
                ctx.first_para_pending=True
            else:
                prefix=f"{info.get('number_fmt')} " if info.get("has_number") else ""
                # number_fmt for sub ends with '.' already
                out+=f'<h{L} id = "link-{info.get("link",1)}">{prefix}{title_html}</h{L}>' + ("\n" if L>1 else "")
                if L==1: ctx.first_para_pending=True
        elif t=="para":
            if is_standalone_image_para(b):
                img_node=[n for n in b["inline"] if n[0]=="image"][0]
                img_html=render_inline_html([img_node],ctx)
                out+=f'<div class = "image">\n  {img_html}\n</div>'
                ctx.first_para_pending=False
            else:
                ctx.para_counter+=1
                pid=ctx.para_counter
                cls=""
                content_nodes=b["inline"]
                if ctx.opts.get("rendering.initials", False) and ctx.first_para_pending and not ctx.in_footnote:
                    cls=' class = "first-para"'
                    if ctx.fmt=="epub":
                        # split first letter
                        content_html=render_initial_epub(content_nodes,ctx)
                        out+=f'<p id = "para-{pid}"{cls}>{content_html}</p>\n'
                        ctx.first_para_pending=False
                        # sidenotes after para
                        out+=render_sidenotes_after_para(ctx,unit)
                        continue
                content_html=render_inline_html(content_nodes,ctx)
                out+=f'<p id = "para-{pid}"{cls}>{content_html}</p>\n'
                ctx.first_para_pending=False
                if top_level:
                    out+=render_sidenotes_after_para(ctx,unit)
        elif t=="list":
            out+=render_list_html(b,ctx,unit)
            ctx.first_para_pending=False
        elif t=="quote":
            inner=render_blocks_html(b["blocks"],ctx,unit,top_level=False)
            out+=f"<blockquote>{inner}</blockquote>\n"
            ctx.first_para_pending=False
        elif t=="rule":
            out+='<p class = "rule">***</p>\n'
        elif t=="code":
            out+=render_code_html(b,ctx)
            ctx.first_para_pending=False
        elif t=="table":
            out+=render_table_html(b,ctx)
            ctx.first_para_pending=False
        elif t=="html":
            raw=b["text"]
            if ctx.opts.get("crowbook.html_as_text", True):
                # escaped lines, no p wrapper
                esc="\n".join(nnbsp_escape_html(line,ctx) if line else "" for line in raw.split("\n"))
                out+=esc+"\n"
            else:
                pass
        else:
            pass
    return out

def render_initial_epub(nodes,ctx):
    # wrap first character of first text node in span.initial
    # Work on rendered html: find first text character? Simpler manipulate nodes copy
    import copy
    nodes=list(nodes)
    for idx,n in enumerate(nodes):
        if n[0]=="text" and n[1]:
            first=n[1][0]; rest=n[1][1:]
            new_nodes=nodes[:idx]+[("text",first)]+(([("text",rest)] if rest else []))+nodes[idx+1:]
            # render first separately
            html=render_inline_html(new_nodes,ctx)
            # html begins with first char (escaped maybe). wrap first char
            # Instead build manually:
            first_html=f'<span class = "initial">{html_escape(first)}</span>'
            rest_nodes=nodes[:idx]+(([("text",rest)] if rest else []))+nodes[idx+1:]
            return first_html+render_inline_html(rest_nodes,ctx)
        elif n[0] in ("emph","strong"):
            # recurse into
            inner=render_initial_epub(n[1],ctx)
            tag="em" if n[0]=="emph" else "b"
            rest=nodes[idx+1:]
            return f"<{tag}>{inner}</{tag}>"+render_inline_html(rest,ctx)
    return render_inline_html(nodes,ctx)

def render_sidenotes_after_para(ctx,unit):
    if ctx.fmt not in ("html","epub","html_dir"): return ""
    if not ctx.opts.get("html.side_notes", False): return ""
