        blocks=item["blocks"]
        raw=item.get("raw_first","")
        task_match=re.match(r"^\[([ xX])\]\s+(.*)$", raw)
        if task_match:
            checked = task_match.group(1).lower()=="x"
            # crowbook quirk: task item rendered without <li>, checkbox before para
            # Need reconstruct blocks with task marker removed: our blocks were parsed with marker text; strip from first para text nodes is hard.
            # Instead render blocks and strip marker via string replace on rendered html text segment
            inner=render_blocks_html(blocks,ctx,unit,top_level=False)
            # remove [ ] / [x] from first occurrence in text
            inner=re.sub(r"\[[ xX]\]\s+", "", inner, count=1)
            checkbox='<input type = "checkbox" disabled = "" checked = "" />' if checked else '<input type = "checkbox" disabled = "" />'
