        if text=="":
            continue
        out+=f'<span style="{style}">{esc}</span>'
    out+="\n</pre>"
    return out

def get_theme_name(ctx):
    # specific format overrides
    specific=None
    if ctx.fmt=="html" or ctx.fmt=="html_dir": specific=ctx.opts.get("html.highlight.theme")
    elif ctx.fmt=="epub": specific=ctx.opts.get("epub.highlight.theme")
