        unit_dir=""
        if self.current_unit and self.current_unit.get("path"):
            unit_dir=os.path.dirname(self.current_unit["path"])
        if base and base not in (".",):
            cand=os.path.join(self.book.base_dir,base,src) if self.book.base_dir else os.path.join(base,src)
            if os.path.exists(cand): return cand
        # relative to chapter file dir first, then book dir
        if unit_dir:
            cand=os.path.join(unit_dir,src)
