            out+=nnbsp_escape_html(n[1],ctx)
        elif k=="code":
            out+=f"<code>{html_escape(n[1])}</code>"
        elif k=="emph": out+=f"<em>{render_inline_html(n[1],ctx,in_alt)}</em>"
        elif k=="strong": out+=f"<b>{render_inline_html(n[1],ctx,in_alt)}</b>"
        elif k=="strike": out+=f"<del>{render_inline_html(n[1],ctx,in_alt)}</del>"
        elif k=="sup": out+=f"<sup>{render_inline_html(n[1],ctx,in_alt)}</sup>"
        elif k=="sub": out+=f"<sub>{render_inline_html(n[1],ctx,in_alt)}</sub>"
