            out+=render_code_html(b,ctx)
            ctx.first_para_pending=False
        elif t=="table":
            out+=render_table_html(b,ctx)
            ctx.first_para_pending=False
        elif t=="html":
            raw=b["text"]
            if ctx.opts.get("crowbook.html_as_text", True):
                # escaped lines, no p wrapper
                esc="\n".join(nnbsp_escape_html(line,ctx) if line else "" for line in raw.split("\n"))
                out+=esc+"\n"
            else:
                pass
        else:
            pass
    return out

def render_initial_epub(nodes,ctx):
    # wrap first character of first text node in span.initial
    # Work on rendered html: find first text character? Simpler manipulate nodes copy
    import copy
    nodes=list(nodes)
    for idx,n in enumerate(nodes):
        if n[0]=="text" and n[1]:
            first=n[1][0]; rest=n[1][1:]
            new_nodes=nodes[:idx]+[("text",first)]+(([("text",rest)] if rest else []))+nodes[idx+1:]
            # render first separately
            html=render_inline_html(new_nodes,ctx)
            # html begins with first char (escaped maybe). wrap first char
            # Instead build manually:
            first_html=f'<span class = "initial">{html_escape(first)}</span>'
            rest_nodes=nodes[:idx]+(([("text",rest)] if rest else []))+nodes[idx+1:]
            return first_html+render_inline_html(rest_nodes,ctx)
        elif n[0] in ("emph","strong"):
            # recurse into
            inner=render_initial_epub(n[1],ctx)
            tag="em" if n[0]=="emph" else "b"
            rest=nodes[idx+1:]
            return f"<{tag}>{inner}</{tag}>"+render_inline_html(rest,ctx)
    return render_inline_html(nodes,ctx)

def render_sidenotes_after_para(ctx,unit):
    if ctx.fmt not in ("html","epub","html_dir"): return ""
    if not ctx.opts.get("html.side_notes", False): return ""
    # footnote_refs collected during this para? Our ctx.footnote_refs is per unit accumulated; we need per-para tracking.
    # We use ctx._para_footnotes set by render_blocks? Simplified: refs added since last call stored in ctx._new_footnotes
    refs=getattr(ctx,"_new_footnotes",[])
    if not refs: return ""
    ctx._new_footnotes=[]
    out=""
    footnotes=unit.get("footnotes",{})
    for label in refs:
        if label not in footnotes: continue
        out+=render_one_sidenote(ctx,unit,label,footnotes[label])
    return out

def render_one_sidenote(ctx,unit,label,fblocks):
    # track that this footnote has been rendered as sidenote to avoid end notes
    if not hasattr(ctx,"_sidenote_rendered"): ctx._sidenote_rendered=set()
    ctx._sidenote_rendered.add((unit["index"],label))
    saved_in=ctx.in_footnote; ctx.in_footnote=True
    inner=render_blocks_html(fblocks,ctx,unit,top_level=False)
    ctx.in_footnote=saved_in
    if ctx.fmt=="epub":
        return (f'<div class = "sidenote">\n<p class = "note-number">\n  <a href = "#note-source-{label}">[{label}]</a>\n</p>\n <a id = "note-dest-{label}" />{inner}\n</div>\n')
    else:
        u=unit["index"]+1
        return (f'<div class = "sidenote">\n<p class = "note-number">\n  <a rel = "footnote" href = "#note-source-{u}-{label}">[{label}]</a>\n</p>\n <aside class = "footnote" id = "note-dest-{u}-{label}">{inner}</aside>\n</div>\n')

def render_list_html(b,ctx,unit):
    ordered=b["ordered"]; start=b.get("start")
    if ordered:
        out=f'<ol start = "{start}">\n' if start and start!=1 else "<ol>\n"
        close="</ol>\n"
    else:
        out="<ul>\n"; close="</ul>\n"
    for item in b["items"]:
        blocks=item["blocks"]
        raw=item.get("raw_first","")
        task_match=re.match(r"^\[([ xX])\]\s+(.*)$", raw)
        if task_match:
            checked = task_match.group(1).lower()=="x"
            # crowbook quirk: task item rendered without <li>, checkbox before para
            # Need reconstruct blocks with task marker removed: our blocks were parsed with marker text; strip from first para text nodes is hard.
            # Instead render blocks and strip marker via string replace on rendered html text segment
            inner=render_blocks_html(blocks,ctx,unit,top_level=False)
            # remove [ ] / [x] from first occurrence in text
            inner=re.sub(r"\[[ xX]\]\s+", "", inner, count=1)
            checkbox='<input type = "checkbox" disabled = "" checked = "" />' if checked else '<input type = "checkbox" disabled = "" />'
            out+=checkbox+inner
            continue
        inner=render_blocks_html(blocks,ctx,unit,top_level=False)
        # inner for list items: paragraphs already <p>...</p>\n and nested lists
        # Original formats: <li><p ..>a</p>\n</li>\n  and nested list inside li before </li>
        inner_stripped=inner
        out+=f"<li>{inner_stripped}</li>\n"
    out+=close
    return out

def render_code_html(b,ctx):
    code=b["text"]; lang=b.get("lang")
    mode=ctx.opts.get("rendering.highlight","syntect")
    if mode not in ("syntect","highlight.js","none"):
        if not ctx.highlight_error_emitted:
            LOG.error(f"rendering.highlight set to '{mode}', not a valid value"); ctx.highlight_error_emitted=True
        mode="none"
    if mode!="syntect":
        lang_attr=f' class = "language-{lang}"' if lang else ""
        # Determine class format: with lang <code class = "language-python">, without?
        if lang:
            return f'<pre><code class = "language-{lang}">{html_escape(code)}</code></pre>\n'
        else:
            return f'<pre><code>{html_escape(code)}</code></pre>\n'
    # syntect
    theme_name=get_theme_name(ctx)
    palette=theme_for(theme_name)
    tokens=tokenize_code(code, lang)
    out="<pre>"
    for kind,text in tokens:
        color=palette.get(kind, palette["default"])
        bold = kind in ("keyword","type") and False  # InspiredGitHub keywords bold? rust fn was bold
        # For rust etc keyword bold observed; python print not bold
        style=""
        # approximate: keywords in non-python are bold
        if kind=="keyword" and (lang or "").lower() not in ("python","py"):
            style=f'font-weight:bold;color:{color};'
        elif kind=="type":
            style=f'font-weight:bold;color:{color};'
        else:
            style=f'color:{color};'
        esc=html_escape(text).replace("'","&#39;").replace('"',"&quot;")
        if text=="":
            continue
        out+=f'<span style="{style}">{esc}</span>'
    out+="\n</pre>"
    return out

def get_theme_name(ctx):
    # specific format overrides
    specific=None
    if ctx.fmt=="html" or ctx.fmt=="html_dir": specific=ctx.opts.get("html.highlight.theme")
    elif ctx.fmt=="epub": specific=ctx.opts.get("epub.highlight.theme")
    elif ctx.fmt=="tex": specific=ctx.opts.get("tex.highlight.theme")
    theme=specific or ctx.opts.get("rendering.highlight.theme","InspiredGitHub")
    if theme not in KNOWN_THEMES:
        if not ctx.theme_error_emitted:
            LOG.error(f'could not set syntect theme to {theme}, defaulting to "InspiredGitHub"'); ctx.theme_error_emitted=True
        return "InspiredGitHub"
    return theme

def render_table_html(b,ctx):
    out='<div class = "table">\n    <table>\n'
    out+="<tr>\n"
    out+="".join(f"<th>{render_inline_html(c,ctx)}</th>" for c in b["headers"])+"</tr>\n"
    for row in b["rows"]:
        out+="<tr>\n"
        out+="".join(f"<td>{render_inline_html(c,ctx)}</td>" for c in row)+"</tr>\n"
    out+="\n    </table>\n</div>\n"
    return out

def render_notes_section(ctx,unit):
    if ctx.opts.get("html.side_notes", False):
        return ""
    refs=ctx.footnote_refs
    if not refs: return ""
    footnotes=unit.get("footnotes",{})
    # order by first reference (refs already) but only those defined
    labels=[l for l in refs if l in footnotes]
    if not labels: return ""
    loc=ctx.loc
    if ctx.fmt=="epub":
        out='<div class = "notes" >\n <h2 class = "notes">'+loc["notes"]+'</h2>\n<table class = "notes">\n'
        for label in labels:
            saved=ctx.in_footnote; ctx.in_footnote=True
            inner=render_blocks_html(footnotes[label],ctx,unit,top_level=False)
            ctx.in_footnote=saved
            out+='<tr class = "notes">\n <td class = "note-number">\n  <p class = "note-number">\n  <a href = "#note-source-'+str(label)+'">['+str(label)+']</a>\n</p>\n\n </td>\n <td class = "note">\n  <a id = "note-dest-'+str(label)+'" />'+inner+'\n  </td>\n</tr>\n'
        out+="</table>\n</div>\n"
        return out
    else:
        u=unit["index"]+1
        out='<section class = "notes" >\n <h2 class = "notes">'+loc["notes"]+'</h2>\n<table class = "notes">\n'
        for label in labels:
            saved=ctx.in_footnote; ctx.in_footnote=True
            inner=render_blocks_html(footnotes[label],ctx,unit,top_level=False)
            ctx.in_footnote=saved
            out+='<tr class = "notes">\n <td class = "note-number">\n  <p class = "note-number">\n  <a rel = "footnote" href = "#note-source-'+f"{u}-{label}"+'">['+str(label)+']</a>\n</p>\n\n </td>\n <td class = "note">\n  <aside class = "footnote" id = "note-dest-'+f"{u}-{label}"+'">'+inner+'</aside>\n  </td>\n</tr>\n'
        out+="</table>\n</section>\n"
        return out

