def build_toc_tree(entries):
    root=[]; stack=[(-2,root)]  # level, children list container node?
    # Use node dicts {entry, children}
    nodes=[]
    stack=[]  # list of node
    for e in entries:
        node={"entry":e,"children":[],"level":e["level"]}
        while stack and stack[-1]["level"]>=e["level"]:
            stack.pop()
        if stack:
            stack[-1]["children"].append(node)
        else:
            nodes.append(node)
        stack.append(node)
    return nodes

