    contents=[]
    allflags={"strike":False,"task":False,"code":False,"images":False,"tables":False}
    for unit in book.units:
        for b in unit["blocks"]:
            f=scan_blocks_flags([b])
            for k in allflags: allflags[k]=allflags[k] or f[k]
        for fb in unit.get("footnotes",{}).values():
            f=scan_blocks_flags(fb)
            for k in allflags: allflags[k]=allflags[k] or f[k]
    for unit in book.units:
        ctx.current_unit=unit; ctx.footnote_refs=[]; ctx.first_para_pending=False
        if unit["kind"]=="part":
