            title=render_inline_tex(info["title_nodes"],ctx)
            prefix=""
            if ctx.opts.get("rendering.part.reset_counter", True): prefix="\\setcounter{chapter}{0}"
            contents.append(f"{prefix}\\part{{{title}}}\n\\label{{chapter-{unit['index']}}}\n")
            continue
        entry=unit["entry"]
        body=""
        # explicit setcounter placed before first numbered chapter heading - handled inside? We place before body if explicit and first heading is chapter
        # Render blocks with label insertion
        blocks=unit["blocks"]
        # Determine label position
        rendered=""
        first_block_heading = blocks and blocks[0].get("type")=="heading"
        if entry.explicit is not None:
            # setcounter before first heading; if first block heading, body rendering will start with it - we insert before
            rendered+=f"\\setcounter{{chapter}}{{{entry.explicit-1}}}\n"
        if not first_block_heading:
            rendered+=f"\\label{{chapter-{unit['index']}}}\n"
        for idx,b in enumerate(blocks):
            piece=render_blocks_tex([b],ctx,unit)
            rendered+=piece
            if idx==0 and first_block_heading:
                rendered+=f"\\label{{chapter-{unit['index']}}}\n"
        # footnotes
        if ctx.footnote_refs:
