        return plain_text_of_inline(nodes)
    tex_class=o.get("tex.class","book")
    margin_left=o.get("tex.margin.left") or ("2.5cm" if tex_class=="book" else "2cm")
    margin_right=o.get("tex.margin.right") or ("1.5cm" if tex_class=="book" else "2cm")
    cover_path=o.get("cover") or ""
    cctx={
        "class":tex_class,
