        "use_strikethrough":allflags["strike"],"use_taskitem":allflags["task"],
        "initials":bool(o.get("rendering.initials",False)),
        "stdpage":bool(o.get("tex.stdpage",False)),
        "papersize":o.get("tex.paper.size","a5paper"),
        "margin_top":o.get("tex.margin.top","2cm"),"margin_bottom":o.get("tex.margin.bottom","1.5cm"),
        "margin_left":margin_left,"margin_right":margin_right,
        "use_cover":bool(o.get("tex.cover",False)),"cover_path":cover_path,
        "date":tex_escape(str(o.get("date") or ""),ctx),"has_date":bool(o.get("date")),
        "book": tex_class=="book",
