                    # original adds blank line inside braces: content ends with \n\n then }
                    # Our inner ends \n\n so okay but braces formatting on new line in examples: }\n - inner ends with \n\n, then } gives blank line before }
                    # Already appended } directly after inner (which ends \n\n) -> matches "\n\n}"
            rendered+=fn_text+"\n"
