        return plain_text_of_inline(nodes)
    tex_class=o.get("tex.class","book")
    margin_left=o.get("tex.margin.left") or ("2.5cm" if tex_class=="book" else "2cm")
    margin_right=o.get("tex.margin.right") or ("1.5cm" if tex_class=="book" else "2cm")
    cover_path=o.get("cover") or ""
    cctx={
        "class":tex_class,
        "has_tex_size": o.get("tex.font.size") is not None,
        "tex_size": str(o.get("tex.font.size") or ""),
        "xelatex": o.get("tex.command","xelatex")=="xelatex",
        "tex_lang": TEX_LANG.get(str(o.get("lang","en")).replace("_","-").split("-")[0].lower(),"english"),
        "author":tex_escape(meta_plain(o.get("author","")),ctx),
        "title":tex_escape(meta_plain(o.get("title","")),ctx),
        "description":tex_escape(meta_plain(o.get("description")),ctx),
        "use_strikethrough":allflags["strike"],"use_taskitem":allflags["task"],
        "initials":bool(o.get("rendering.initials",False)),
        "stdpage":bool(o.get("tex.stdpage",False)),
        "papersize":o.get("tex.paper.size","a5paper"),
        "margin_top":o.get("tex.margin.top","2cm"),"margin_bottom":o.get("tex.margin.bottom","1.5cm"),
        "margin_left":margin_left,"margin_right":margin_right,
        "use_cover":bool(o.get("tex.cover",False)),"cover_path":cover_path,
        "date":tex_escape(str(o.get("date") or ""),ctx),"has_date":bool(o.get("date")),
        "book": tex_class=="book",
        "subtitle":meta_tex(o.get("subtitle")),
        "has_autograph":bool(o.get("autograph")),"autograph":meta_tex(o.get("autograph")),
        "has_version":bool(o.get("version")),"version":tex_escape(str(o.get("version") or ""),ctx),
        "has_author":bool(o.get("author")),"has_license":bool(o.get("license")),"license":meta_tex(o.get("license")),
        "use_codeblocks":allflags["code"],"use_images":allflags["images"],"use_tables":allflags["tables"],
