        elif k=="code": out+=f"\\mdcode{{{tex_escape(n[1],ctx)}}}"
        elif k=="emph": out+=f"\\emph{{{render_inline_tex(n[1],ctx)}}}"
        elif k=="strong": out+=f"\\mdstrong{{{render_inline_tex(n[1],ctx)}}}"
        elif k=="strike": out+=f"\\sout{{{render_inline_tex(n[1],ctx)}}}"
        elif k=="sup": out+=f"\\textsuperscript{{{render_inline_tex(n[1],ctx)}}}"
        elif k=="sub": out+=f"\\textsubscript{{{render_inline_tex(n[1],ctx)}}}"
        elif k=="hardbreak": out+="\\mdhardbreak\n"
        elif k=="link":
            href=n[2] or ""; text=render_inline_tex(n[1],ctx)
            new_href,is_internal,tex_key=ctx.resolve_link(href)
            if is_internal and ctx.opts.get("tex.hyperref", True):
