def tex_initial(content):
    # content is tex-rendered; find first alphabetic character sequence of rendered plain? Approx operate on first word characters ignoring tex commands
    # Original works on markdown text before rendering: first letter + rest of first word.
    # Our content may start with tex commands; do simple: locate first letter
    m=re.search(r"[A-Za-zÀ-ÿ]", content)
    if not m: return content
    i=m.start(); first=content[i]
    # rest of word until space or punctuation - in tex rendered, letters follow
    j=i+1
    while j<len(content) and (content[j].isalpha()):
        j+=1
    rest=content[i+1:j]
    return content[:i]+f"\\lettrine{{{first}}}{{{rest}}}"+content[j:]

def render_list_tex(b,ctx,unit):
    if b["ordered"]:
        out="\\begin{enumerate}\n"
        if b.get("start") and b["start"]!=1: out+=f"\\setcounter{{enumi}}{{{b['start']-1}}}\n"
        close="\\end{enumerate}\n"
    else:
        out="\\begin{itemize}\n"; close="\\end{itemize}\n"
    for item in b["items"]:
        raw=item.get("raw_first","")
        task=re.match(r"^\[([ xX])\]\s+(.*)$",raw)
        inner=render_blocks_tex(item["blocks"],ctx,unit,False)
        if task:
            inner=re.sub(r"\[[ xX]\]\s+","",inner,count=1)
            # ulem/amssymb checkbox
            if task.group(1).lower()=="x": out+=f"\\item[$\\boxtimes$] {inner}"
            else: out+=f"\\item[$\\square$] {inner}"
        else:
            out+=f"\\item {inner}"
