def scan_blocks_flags(blocks):
    flags={"strike":False,"task":False,"code":False,"images":False,"tables":False}
    def scan_inline(nodes):
        for n in nodes or []:
            if n[0]=="strike": flags["strike"]=True
            if n[0]=="image": flags["images"]=True
            if n[0] in ("emph","strong","link","sup","sub"): scan_inline(n[1])
    def scan(blocks):
        for b in blocks:
            if b.get("type")=="code": flags["code"]=True
            if b.get("type")=="table": flags["tables"]=True
            if b.get("type")=="quote": scan(b["blocks"])
            if b.get("type")=="list":
                for item in b["items"]:
                    if re.match(r"^\[[ xX]\]\s",item.get("raw_first","")): flags["task"]=True
                    scan(item["blocks"])
            if "inline" in b: scan_inline(b["inline"])
            if b.get("type")=="table":
