import sys, random
sys.path.insert(0,'/tmp')
from compare import compare

WORDS=["alpha","beta","gamma","delta","café","l'homme","word","test","chapter","story","Bonjour","élan"]
def inline(r):
    parts=[]
    for _ in range(r.randint(1,6)):
        w=" ".join(r.sample(WORDS,r.randint(1,4)))
        t=r.random()
        if t<0.1: parts.append(f"*{w}*")
        elif t<0.2: parts.append(f"**{w}**")
        elif t<0.25: parts.append(f"`{w}`")
        elif t<0.3: parts.append(f"[link {w}](http://example.com/{r.randint(1,9)})")
        elif t<0.35: parts.append(f"\"{w}\"")
        elif t<0.4: parts.append(f"{w} !")
        else: parts.append(w)
    return " ".join(parts)+"."
def md_for_seed(seed):
    r=random.Random(seed)
    lines=[f"# Chapter {seed} Heading", ""]
    for i in range(r.randint(3,8)):
        t=r.random()
        if t<0.45: lines.append(inline(r)); lines.append("")
        elif t<0.55: lines.append(f"## Section {i}"); lines.append(""); lines.append(inline(r)); lines.append("")
        elif t<0.65:
            for j in range(r.randint(2,4)): lines.append(f"- item {inline(r)[:-1]}")
            lines.append("")
        elif t<0.72:
            for j in range(1,r.randint(2,4)): lines.append(f"{j}. item {inline(r)[:-1]}")
            lines.append("")
        elif t<0.79: lines.append("> "+inline(r)); lines.append(">"); lines.append("> "+inline(r)); lines.append("")
        elif t<0.85: lines.append("```python"); lines.append(f"x = {r.randint(1,99)} # comment"); lines.append("print(x)"); lines.append("```"); lines.append("")
        elif t<0.9: lines.append("| A | B |"); lines.append("|---|---|"); lines.append(f"| {r.randint(1,9)} | {inline(r)[:-1]} |"); lines.append("")
        elif t<0.95: lines.append(inline(r)+"[^n"+str(i)+"]"); lines.append(""); lines.append(f"[^n{i}]: Note {inline(r)[:-1]}."); lines.append("")
        else: lines.append("---"); lines.append("")
    return "\n".join(lines)

ok=0; total=0; fails=[]
for seed in range(30):
    md=md_for_seed(seed)
    files={"ch.md":md,"ch2.md":md_for_seed(seed+1000),"book.book":"title: Fuzz\nauthor: Tester\nlang: en\noutput.html: o.html\noutput.tex: o.tex\noutput.epub: o.epub\n+ ch.md\n+ ch2.md\n"}
    total+=1
    if compare(f"fuzz{seed}",{"files":files,"args":["book.book"],"stdin":"","env":{}}): ok+=1
    else: fails.append(seed)
print(f"{ok}/{total} fuzz passed; fails={fails}")
