        self.enabled=False; self.lines=[]; self.drawn=False
    def configure(self):
        try: self.enabled = sys.stderr.isatty() and LOG.fancy
        except Exception: self.enabled=False
    def _pad(self,line):
        try: w=shutil.get_terminal_size((80,24)).columns
        except Exception: w=80
        return line + " " * max(0, w - len(line))
    def draw(self):
        if not self.enabled or not self.lines: return
        lines=[self._pad(l) for l in self.lines]
        if not self.drawn:
            sys.stderr.write("\\r\\n".join(lines)); sys.stderr.flush(); self.drawn=True
        else:
            n=len(lines)
            out=""
            if n>1: out+=f"\\x1b[{n-1}A"
            for idx,line in enumerate(lines):
                out+="\\r\\x1b[2K"+line
                if idx<n-1: out+="\\x1b[1B"
            sys.stderr.write(out); sys.stderr.flush()
    def set_lines(self,lines):
        if not self.enabled: return
        self.lines=list(lines); self.draw()
    def bar_line(self,done,total):
        try: w=shutil.get_terminal_size((80,24)).columns
        except Exception: w=80
        suffix=f" {done}/{total}"; barw=max(0,w-len(suffix))
        filled=int(barw*done/total) if total else barw
        return "█"*filled + "░"*(barw-filled) + suffix

